async function saveBusinessProfile(){
 const b={name:document.querySelector('#b-name')?.value?.trim()||'',category:document.querySelector('#b-cat')?.value||'',province:document.querySelector('#b-prov')?.value?.trim()||'',city:document.querySelector('#b-city')?.value?.trim()||'',zone:document.querySelector('#b-zone')?.value?.trim()||'',description:document.querySelector('#b-desc')?.value?.trim()||'',address:document.querySelector('#b-address')?.value?.trim()||'',website:document.querySelector('#b-web')?.value?.trim()||'',instagram:document.querySelector('#b-inst')?.value?.trim()||'',hours:document.querySelector('#b-hours')?.value?.trim()||''};
 if(!sb||!state.authUser)return showLogin();
 const {data:bp,error:be}=await sb.from('business_profiles').select('id').eq('user_id',state.authUser.id).maybeSingle();if(be)return toast(be.message);let id=bp?.id;
 const lookup=async(table,col,value)=>{if(!value)return null;const {data}=await sb.from(table).select('id').ilike(col,value).limit(1).maybeSingle();return data?.id||null};
 const provinceId=document.querySelector('#b-prov')?.value||null, cityId=document.querySelector('#b-city')?.value||null, zoneId=document.querySelector('#b-zone')?.value||null, categoryId=document.querySelector('#b-cat')?.value||null;
 let logoUrl=state.business.logo||'';const logoFile=document.querySelector('#b-photo')?.files?.[0];if(logoFile){try{logoUrl=await uploadProfileImage(logoFile,'business')}catch(e){return toast(e.message||'No se pudo subir la imagen')}} const payload={user_id:state.authUser.id,responsible_name:state.authUser.user_metadata?.full_name||state.authUser.email?.split('@')[0]||'Responsable',business_name:b.name,category_id:categoryId,description:b.description,province_id:provinceId,city_id:cityId,zone_id:zoneId,address:b.address,website:b.website,social_links:{instagram:b.instagram},hours:{text:b.hours},logo_url:logoUrl||null,contact_permission:state.business.contact!==false,public_zone_only:true};
 let r=id?await sb.from('business_profiles').update(payload).eq('id',id):await sb.from('business_profiles').insert(payload);if(r.error)return toast(r.error.message);state.business={...b,logo:logoUrl||state.business.logo,province:catalogs.provinces.find(x=>x.id===provinceId)?.name||'',city:catalogs.cities.find(x=>x.id===cityId)?.name||'',zone:catalogs.zones.find(x=>x.id===zoneId)?.name||'',category:catalogs.categories.find(x=>x.id===categoryId)?.name||''};closeModal();render();toast('Perfil de negocio guardado')
}

function openAvailability(){openModal('Mi disponibilidad',`<div class="availability-options">${['Disponible ahora','Disponible hoy','Disponible mañana','Esta semana','Fin de semana','No disponible'].map(x=>`<button class="availability-option ${state.worker.availability===x?'selected':''}" onclick="setAvailability('${x}')"><span>${x==='No disponible'?'○':'●'}</span>${x}<i>›</i></button>`).join('')}</div><label>Nota opcional<textarea id="avail-note" placeholder="Ej.: disponible para turno noche"></textarea></label><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="saveAvailability()">Guardar</button></div>`)}
function setAvailability(v){state.worker._pendingAvailability=v;openAvailability()}
async function saveAvailability(){const label=state.worker._pendingAvailability||state.worker.availability;delete state.worker._pendingAvailability;if(!sb||!state.authUser)return showLogin();const map={'Disponible ahora':'now','Disponible hoy':'today','Disponible mañana':'tomorrow','Esta semana':'this_week','Fin de semana':'weekends'};if(label==='No disponible'){const {error}=await sb.rpc('disable_worker_availability');if(error)return toast(error.message)}else{const now=new Date();const starts=new Date(now);let expires=new Date(now);if(label==='Disponible ahora'){expires.setHours(23,59,59,999)}else if(label==='Disponible hoy'){expires.setHours(23,59,59,999)}else if(label==='Disponible mañana'){starts.setDate(starts.getDate()+1);starts.setHours(0,0,0,0);expires=new Date(starts);expires.setHours(23,59,59,999)}else if(label==='Esta semana'){expires.setDate(expires.getDate()+7)}else if(label==='Fin de semana'){expires.setDate(expires.getDate()+7)}const {error}=await sb.rpc('set_worker_availability',{p_availability_type:map[label],p_starts_at:starts.toISOString(),p_expires_at:expires.toISOString(),p_notes:document.querySelector('#avail-note')?.value||null});if(error)return toast(error.message)}state.worker.availability=label;closeModal();render();toast('Disponibilidad actualizada')}
function openBoost(){openModal('Destacarme',`<p class="muted">El boost aumenta visibilidad, pero nunca reemplaza la relevancia, disponibilidad o coincidencia por zona.</p><div class="boost-option"><div><b>24 horas</b><span>Visibilidad destacada durante 24 h</span></div><strong>24 h</strong><button class="primary" onclick="requestBoost('24 horas')">Elegir</button></div><div class="boost-option"><div><b>7 días</b><span>Visibilidad destacada durante 7 días</span></div><strong>7 d</strong><button class="primary" onclick="requestBoost('7 días')">Elegir</button></div>`)}
async function requestBoost(t){if(!sb||!state.authUser)return showLogin();const {data:wp}=await sb.from('worker_profiles').select('id').eq('user_id',state.authUser.id).maybeSingle();if(!wp)return toast('Primero completá tu perfil de trabajador');const type=t==='24 horas'?'24_hours':'featured_7_days';const {error}=await sb.rpc('request_boost',{p_worker_id:wp.id,p_boost_type:type});if(error)return toast(error.message);closeModal();toast(`Boost de ${t} solicitado`) }
async function openReputation(){if(!sb||!state.authUser)return showLogin();const {data,error}=await sb.from('reviews').select('rating,comment,status,created_at').eq('reviewed_user_id',state.authUser.id).eq('status','published').order('created_at',{ascending:false});if(error)return toast(error.message);const rows=data||[];const avg=rows.length?(rows.reduce((a,r)=>a+Number(r.rating||0),0)/rows.length).toFixed(1):'Nuevo';openModal('Mi reputación',`<div class="rating-big">★ <strong>${esc(avg)}</strong></div><p class="muted">${rows.length?`${rows.length} reseña${rows.length===1?'':'s'} publicada${rows.length===1?'':'s'}.`:'Todavía no tenés reseñas publicadas.'}</p><div class="cards-list">${rows.map(r=>`<div class="info-card"><b>⭐ ${r.rating}/5</b><p>${esc(r.comment||'Sin comentario')}</p></div>`).join('')||empty('Sin reseñas','La reputación aparece después de interacciones reales.')}</div>`)}
async function openFilters(){await loadCatalogs();const provinceId=selectedId(catalogs.provinces,state.filters.province);const cityId=selectedId(citiesForProvince(provinceId),state.filters.city);const zoneId=selectedId(zonesForCity(cityId),state.filters.zone);const categoryId=selectedId(catalogs.categories,state.filters.category);const skillId=selectedId(catalogs.skills,state.filters.skill);openModal('Filtros de búsqueda',`<label>Disponibilidad<select id="f-av"><option value="">Cualquiera</option><option>Disponible ahora</option><option>Disponible hoy</option><option>Disponible mañana</option><option>Esta semana</option><option>Fin de semana</option></select></label><div class="grid two"><label>Provincia<select id="f-prov" onchange="refreshFilterLocations()">${optionList(catalogs.provinces,provinceId,'Todas')}</select></label><label>Ciudad<select id="f-city" onchange="refreshFilterZones()">${optionList(citiesForProvince(provinceId),cityId,'Todas')}</select></label><label>Zona<select id="f-zone">${optionList(zonesForCity(cityId),zoneId,'Todas')}</select></label><label>Categoría<select id="f-cat" onchange="refreshFilterSkills()">${optionList(catalogs.categories,categoryId,'Todas')}</select></label><label>Skill<select id="f-skill">${optionList(catalogs.skills.filter(x=>!categoryId||x.category_id===categoryId),skillId,'Todas')}</select></label><label>Experiencia<select id="f-exp"><option value="">Cualquiera</option><option>1+ año</option><option>3+ años</option><option>5+ años</option></select></label><label>Movilidad<select id="f-mob"><option value="">Cualquiera</option><option>A pie</option><option>Bicicleta</option><option>Moto</option><option>Auto</option><option>Transporte público</option></select></label></div><div class="modal-actions"><button class="secondary" onclick="clearFilters()">Limpiar</button><button class="primary" onclick="applyFilters()">Aplicar filtros</button></div>`)}
function refreshFilterLocations(){const provinceId=document.querySelector('#f-prov')?.value||'';const city=document.querySelector('#f-city');if(city)city.innerHTML=optionList(citiesForProvince(provinceId),'','Todas');const zone=document.querySelector('#f-zone');if(zone)zone.innerHTML=optionList([], '', 'Elegí primero una ciudad')}
function refreshFilterZones(){const cityId=document.querySelector('#f-city')?.value||'';const zone=document.querySelector('#f-zone');if(zone)zone.innerHTML=optionList(zonesForCity(cityId),'','Todas')}
function refreshFilterSkills(){const categoryId=document.querySelector('#f-cat')?.value||'';const skill=document.querySelector('#f-skill');if(skill)skill.innerHTML=optionList(catalogs.skills.filter(x=>!categoryId||x.category_id===categoryId),'','Todas')}
function applyFilters(){const pid=document.querySelector('#f-prov')?.value||'',cid=document.querySelector('#f-city')?.value||'',zid=document.querySelector('#f-zone')?.value||'',catid=document.querySelector('#f-cat')?.value||'',sid=document.querySelector('#f-skill')?.value||'';state.filters={availability:document.querySelector('#f-av').value,province:catalogs.provinces.find(x=>x.id===pid)?.name||'',city:catalogs.cities.find(x=>x.id===cid)?.name||'',zone:catalogs.zones.find(x=>x.id===zid)?.name||'',category:catalogs.categories.find(x=>x.id===catid)?.name||'',experience:document.querySelector('#f-exp').value,mobility:document.querySelector('#f-mob').value,skill:catalogs.skills.find(x=>x.id===sid)?.name||''};closeModal();state.screen='search';runSearch()}
function clearFilters(){state.filters={availability:'',category:'',province:'',city:'',zone:'',experience:'',mobility:'',skill:''};closeModal();toast('Filtros limpiados')}
function filterWorkers(list){return list.filter(w=>{const f=state.filters;return(!f.category||w.category===f.category)&&(!f.zone||w.zone.toLowerCase().includes(f.zone.toLowerCase()))&&(!f.city||w.city.toLowerCase().includes(f.city.toLowerCase()))&&(!f.mobility||w.mobility===f.mobility)&&(!f.skill||w.skills.some(s=>s.toLowerCase().includes(f.skill.toLowerCase())))&&(!f.availability||w.availability===f.availability)}).filter(w=>!document.querySelector('#search-q')||!document.querySelector('#search-q').value||`${w.name} ${w.category} ${w.skills.join(' ')}`.toLowerCase().includes(document.querySelector('#search-q').value.toLowerCase()))}
async function runSearch(type=''){if(type==='now')state.filters.availability='Disponible ahora';state.screen='search';if(sb&&state.role==='business'){const f=state.filters;const availabilityMap={'Disponible ahora':'now','Disponible hoy':'today','Disponible mañana':'tomorrow','Esta semana':'this_week','Fin de semana':'weekends'};const lookup=async(table,col,value)=>{if(!value)return null;const {data}=await sb.from(table).select('id').ilike(col,value).limit(1).maybeSingle();return data?.id||null};const [provinceId,cityId,zoneId,categoryId,skillId]=await Promise.all([lookup('provinces','name',f.province),lookup('cities','name',f.city),lookup('zones','name',f.zone),lookup('categories','name',f.category),lookup('skills','name',f.skill)]);const query=document.querySelector('#quick-search')?.value||document.querySelector('#search-q')?.value||'';const exp=f.experience==='1+ año'?1:f.experience==='3+ años'?3:f.experience==='5+ años'?5:null;const {data,error}=await sb.rpc('search_workers',{p_province_id:provinceId,p_city_id:cityId,p_zone_id:zoneId,p_category_id:categoryId,p_skill_id:skillId,p_availability:availabilityMap[f.availability]||null,p_min_experience:exp,p_mobility:f.mobility||null,p_query:query,p_limit:50,p_offset:0});if(error)return toast(error.message);const rows=data||[];const ids=rows.map(w=>w.worker_id);let meta={};if(ids.length){const [cats,skills,profiles]=await Promise.all([sb.from('worker_categories').select('worker_id,categories(name)').in('worker_id',ids),sb.from('worker_skills').select('worker_id,skills(name)').in('worker_id',ids),sb.from('worker_profiles').select('id,provinces(name),cities(name),zones(name)').in('id',ids)]);const catMap={};(cats.data||[]).forEach(x=>{if(!catMap[x.worker_id])catMap[x.worker_id]=[];if(x.categories?.name)catMap[x.worker_id].push(x.categories.name)});const skillMap={};(skills.data||[]).forEach(x=>{if(!skillMap[x.worker_id])skillMap[x.worker_id]=[];if(x.skills?.name)skillMap[x.worker_id].push(x.skills.name)});(profiles.data||[]).forEach(x=>{meta[x.id]={category:catMap[x.id]?.[0]||'',skills:skillMap[x.id]||[],zone:x.zones?.name||'Zona aproximada',city:x.cities?.name||'',province:x.provinces?.name||''}})}state.realWorkers=rows.map(w=>({id:w.worker_id,name:`${w.first_name||''} ${w.last_name||''}`.trim(),initial:(w.first_name||'P')[0],availability:{now:'Disponible ahora',today:'Disponible hoy',tomorrow:'Disponible mañana',this_week:'Esta semana',weekends:'Fin de semana'}[w.availability_type]||'Disponible',zone:meta[w.worker_id]?.zone||'Zona aproximada',city:meta[w.worker_id]?.city||'',category:meta[w.worker_id]?.category||'',skills:meta[w.worker_id]?.skills||[],experience:`${w.experience_years||0} años`,mobility:w.mobility?.selected||'Ver perfil',rating:w.rating_average||'Nuevo',reviews:w.rating_count||0,featured:!!w.is_featured,bio:w.bio||''}));}render()}
async function viewWorker(id){let w=null;if(sb&&state.authUser&&state.role==='business'&&/^[0-9a-f-]{36}$/i.test(id)){const {data:p,error}=await sb.from('worker_profiles').select('id,user_id,first_name,last_name,photo_url,bio,experience_years,experience_description,mobility,profile_completion,rating_average,rating_count,provinces(name),cities(name),zones(name)').eq('id',id).maybeSingle();if(error)return toast(error.message);if(!p)return toast('No encontramos este perfil');const [cat,skills,av,reviews]=await Promise.all([sb.from('worker_categories').select('categories(name)').eq('worker_id',id),sb.from('worker_skills').select('skills(name)').eq('worker_id',id),sb.from('availability').select('availability_type').eq('worker_id',id).eq('is_active',true).order('created_at',{ascending:false}).limit(1).maybeSingle(),sb.from('reviews').select('rating,comment,created_at').eq('reviewed_user_id',p.user_id).eq('status','published').order('created_at',{ascending:false}).limit(5)]);w={id,userId:p.user_id,photo:p.photo_url||'',name:`${p.first_name||''} ${p.last_name||''}`.trim(),initial:(p.first_name||'P')[0],availability:{now:'Disponible ahora',today:'Disponible hoy',tomorrow:'Disponible mañana',this_week:'Esta semana',weekends:'Fin de semana'}[av.data?.availability_type]||'No disponible',zone:p.zones?.name||'Zona aproximada',city:p.cities?.name||'',category:cat.data?.[0]?.categories?.name||'',skills:(skills.data||[]).map(x=>x.skills?.name).filter(Boolean),experience:`${p.experience_years||0} años`,mobility:p.mobility?.selected||'No especificada',rating:p.rating_count?p.rating_average:'Nuevo',reviews:p.rating_count||0,featured:false,bio:p.bio||p.experience_description||'',publishedReviews:reviews.data||[]};}if(!w)return;openModal('Perfil del trabajador',`<div class="worker-detail"><div class="big-avatar">${w.photo?`<img src="${esc(w.photo)}" alt="Foto de ${esc(w.name)}">`:w.initial}</div><span class="featured">${w.featured?'DESTACADO':'PERFIL'}</span><h2>${esc(w.name)}</h2><p class="available-text">● ${esc(w.availability)}</p><p class="muted">${esc(w.category)} · ${esc(w.zone)}, ${esc(w.city)}</p><div class="detail-grid"><div><small>Experiencia</small><b>${esc(w.experience)}</b></div><div><small>Movilidad</small><b>${esc(w.mobility)}</b></div><div><small>Reputación</small><b>⭐ ${esc(w.rating)}</b></div><div><small>Reseñas</small><b>${w.reviews}</b></div></div><h3>Sobre mí</h3><p>${esc(w.bio||'Sin presentación todavía.')}</p><h3>Habilidades</h3><div class="worker-tags">${w.skills.map(s=>`<span>${esc(s)}</span>`).join('')||'<span>Sin habilidades cargadas</span>'}</div><h3>Últimas reseñas</h3><div class="cards-list">${w.publishedReviews?.length?w.publishedReviews.map(r=>`<div class="info-card"><b>⭐ ${Number(r.rating)||0}/5</b><p>${esc(r.comment||'Sin comentario')}</p></div>`).join(''):empty('Sin reseñas publicadas','Las reseñas aparecen después de experiencias reales.')}</div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cerrar</button><button class="secondary" onclick="openReport('${w.userId||''}')">Reportar</button><button class="secondary" onclick="blockUser('${w.userId||''}')">Bloquear</button><button class="primary" onclick="contactWorker('${w.id}')">Contactar por WhatsApp</button><button class="secondary" onclick="openReview('${w.userId||''}',\`${esc(w.name)}\`)">Calificar</button></div>`)}
async function contactWorker(id){if(!sb||!state.authUser)return showLogin();const {data,error}=await sb.rpc('start_worker_contact',{p_worker_id:id});if(error)return toast(error.message);closeModal();if(data?.whatsapp_url)location.href=data.whatsapp_url;else toast('Contacto registrado')}
async function toggleFavorite(id){if(!sb||!state.authUser)return showLogin();const {data:bp}=await sb.from('business_profiles').select('id').eq('user_id',state.authUser.id).maybeSingle();if(!bp)return toast('Primero completá tu perfil de negocio');const exists=await sb.from('favorites').select('id').eq('business_id',bp.id).eq('worker_id',id).maybeSingle();if(exists.data){const {error}=await sb.from('favorites').delete().eq('id',exists.data.id);if(error)return toast(error.message);state.favorites=state.favorites.filter(x=>x!==id);toast('Quitado de Mis candidatos')}else{const {error}=await sb.from('favorites').insert({business_id:bp.id,worker_id:id});if(error)return toast(error.message);state.favorites=[...state.favorites,id];toast('Guardado en Mis candidatos')}await loadSavedWorkers();render()}
async function markAllRead(){if(sb&&state.authUser){const {error}=await sb.rpc('mark_all_notifications_read');if(error)return toast(error.message)}state.notifications.forEach(n=>n.unread=false);render();toast('Notificaciones leídas')}
async function readNotification(i){const n=state.notifications[i];if(sb&&state.authUser&&n?.id){const {error}=await sb.rpc('mark_notification_read',{p_notification_id:n.id});if(error)return toast(error.message)}if(n)n.unread=false;render()}
function openAccountSettings(){const p=state.role==='worker'?state.worker:state.business;const contact=!!p.contact;const status=state.accountStatus||'active';openModal('Cuenta y privacidad',`<div class="settings-list"><div><b>Permitir nuevos contactos</b><span>${state.role==='worker'?'Los negocios pueden solicitar contacto.':'Podés recibir contactos de trabajadores.'}</span><button class="toggle ${contact?'on':''}" onclick="setContactPermission(${!contact})"><i></i></button></div><div><b>Mostrar solo zona aproximada</b><span>La ubicación exacta nunca es pública.</span><button class="toggle on"><i></i></button></div><div><b>Estado de cuenta</b><span>${status==='paused'?'Pausada':'Activa'}</span><button class="secondary" onclick="${status==='paused'?'resumeAccount()':'pauseAccount()'}">${status==='paused'?'Reactivar':'Pausar'}</button></div></div>`)}
async function setContactPermission(value){if(!sb||!state.authUser)return;const table=state.role==='worker'?'worker_profiles':'business_profiles';const {error}=await sb.from(table).update({contact_permission:value}).eq('user_id',state.authUser.id);if(error)return toast(error.message);if(state.role==='worker')state.worker.contact=value;else state.business.contact=value;openAccountSettings();toast(value?'Nuevos contactos permitidos':'Nuevos contactos bloqueados')}
async function blockUser(userId){if(!sb||!state.authUser||!userId)return toast('No se pudo identificar al usuario');const {error}=await sb.rpc('block_user',{p_user_id:userId});if(error)return toast(error.message);closeModal();toast('Usuario bloqueado')}
function openReport(userId){if(!sb||!state.authUser||!userId)return toast('No se pudo identificar al usuario');openModal('Reportar usuario',`<label>Motivo<select id="report-reason"><option>spam</option><option>acoso</option><option>perfil falso</option><option>información engañosa</option><option>comportamiento inapropiado</option><option>otro</option></select></label><label>Detalle opcional<textarea id="report-desc" placeholder="Contanos qué pasó"></textarea></label><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="danger-btn" onclick="submitReport('${userId}')">Enviar reporte</button></div>`)}
async function submitReport(userId){const {error}=await sb.rpc('submit_report',{p_reported_user_id:userId,p_reason:document.querySelector('#report-reason')?.value,p_description:document.querySelector('#report-desc')?.value?.trim()||null});if(error)return toast(error.message);closeModal();toast('Reporte enviado para revisión')}
function openReview(userId,name){if(!sb||!state.authUser||!userId)return;openModal('Calificar experiencia',`<p class="muted">Tu experiencia con ${esc(name)} será moderada antes de publicarse.</p><label>Puntuación<select id="review-rating"><option value="5">★★★★★ 5</option><option value="4">★★★★☆ 4</option><option value="3">★★★☆☆ 3</option><option value="2">★★☆☆☆ 2</option><option value="1">★☆☆☆☆ 1</option></select></label><label>Comentario opcional<textarea id="review-comment"></textarea></label><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="submitReview('${userId}')">Enviar reseña</button></div>`)}
async function submitReview(userId){const {error}=await sb.rpc('submit_review',{p_reviewed_user_id:userId,p_rating:Number(document.querySelector('#review-rating')?.value),p_comment:document.querySelector('#review-comment')?.value?.trim()||null});if(error)return toast(error.message);closeModal();toast('Reseña enviada para moderación')}
async function setAccountStatus(status){if(!sb||!state.authUser)return showLogin();const {error}=await sb.rpc('set_my_account_status',{p_status:status});if(error)return toast(error.message);state.accountStatus=status;if(status==='paused'){state.worker.availability='No disponible';state.business.status='paused';}closeModal();if(status==='paused'){toast('Cuenta pausada. Podés reactivarla cuando quieras.')}else{toast('Cuenta reactivada.');}render()}
function pauseAccount(){openModal('Pausar cuenta',`<div class="danger-box"><b>¿Querés pausar tu cuenta?</b><p>Tu perfil dejará de estar disponible para nuevas búsquedas mientras esté pausado.</p></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="setAccountStatus('paused')">Pausar cuenta</button></div>`)}
function resumeAccount(){setAccountStatus('active')}
function openSafety(){openModal('Seguridad y reportes',`<div class="settings-list"><button onclick="openBlockedUsers()"><b>🚫 Usuarios bloqueados</b><span>Gestionar bloqueos</span></button><button onclick="closeModal();toast('Para reportar un perfil, abrí su ficha y elegí Reportar.')"><b>⚑ Reportar un problema</b><span>Spam, acoso, perfil falso, información engañosa u otro</span></button><div><b>🔒 Seguridad</b><span>No mostramos direcciones exactas ni datos de contacto cuando el usuario no los autoriza.</span></div></div>`)}
async function openBlockedUsers(){if(!sb||!state.authUser)return;const {data,error}=await sb.from('blocks').select('id,blocked_user_id,created_at').eq('blocker_user_id',state.authUser.id).order('created_at',{ascending:false});if(error)return toast(error.message);if(!(data||[]).length)return openModal('Usuarios bloqueados',empty('No hay bloqueos','Todavía no bloqueaste a ningún usuario.'));const ids=data.map(x=>x.blocked_user_id);const {data:users}=await sb.from('users').select('id,email').in('id',ids);const names=Object.fromEntries((users||[]).map(u=>[u.id,u.email||'Usuario']));openModal('Usuarios bloqueados',`<div class="settings-list">${data.map(x=>`<div><b>${esc(names[x.blocked_user_id]||'Usuario')}</b><button class="secondary" onclick="unblockUser('${x.blocked_user_id}')">Desbloquear</button></div>`).join('')}</div>`)}
async function unblockUser(userId){const {error}=await sb.rpc('unblock_user',{p_user_id:userId});if(error)return toast(error.message);openBlockedUsers();toast('Usuario desbloqueado')}
function openTerms(){openModal('Términos y privacidad',`<div class="info-card"><h3>Términos de uso</h3><p>DISPONIBLE conecta personas disponibles con negocios que necesitan personal. La plataforma no es empleadora, no garantiza contratación y no administra el pago del trabajo realizado.</p><p>Los usuarios deben proporcionar información verdadera, respetar a otros usuarios y utilizar la plataforma de forma lícita.</p></div><div class="info-card"><h3>Privacidad</h3><p>La ubicación pública se limita a una zona aproximada. Los datos de contacto se utilizan según los permisos configurados y las funciones de la plataforma.</p></div>`)}
function confirmDelete(){openModal('Eliminar cuenta',`<div class="danger-box"><b>La cuenta dejará de estar activa.</b><p>Tu perfil se marcará como eliminado y dejará de aparecer en nuevas búsquedas. La eliminación física de credenciales se gestiona posteriormente mediante el flujo seguro de cuenta.</p></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="danger-btn" onclick="deleteMyAccount()">Eliminar cuenta</button></div>`)}
async function deleteMyAccount(){if(!sb||!state.authUser)return showLogin();const {error}=await sb.rpc('set_my_account_status',{p_status:'deleted'});if(error)return toast(error.message);toast('Cuenta eliminada del sistema DISPONIBLE.');await logout()}
function empty(title,text){return `<div class="empty"><div>⌁</div><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`}
function navigate(k){state.screen=k;render()}
function goBack(){state.screen='home';render()}
function openMenu(){openModal('Menú',`<div class="menu-list"><button onclick="navigate('profile');closeModal()">👤 Mi perfil</button><button onclick="navigate('notifications');closeModal()">🔔 Notificaciones</button><button onclick="openTerms()">ⓘ Términos y privacidad</button><button onclick="logout();closeModal()">↪ Cerrar sesión</button></div>`)}
function openModal(title,body){closeModal();const m=document.createElement('div');m.className='modal';m.id='modal';m.innerHTML=`<div class="modal-card"><div class="modal-head"><div><span class="eyebrow">DISPONIBLE</span><h2>${esc(title)}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div>${body}</div>`;document.body.append(m)}
function closeModal(){document.querySelector('#modal')?.remove()}
render();

(async()=>{await syncAuth();if(sb)sb.auth.onAuthStateChange(()=>setTimeout(async()=>{await syncAuth();render()},0));render()})();
